package main

import (
	"os"

	"github.com/reimpl/gomplate/internal/cli"
)

func main() {
	os.Exit(cli.Run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// Package funcs contains the template function namespaces.
//
// Each namespace lives in its own file and self-registers in init() via
// RegisterNS (for `ns.Func` style access) and/or RegisterGlobal (for
// top-level template functions like `json` or `add`).
//
// DO NOT change the registration API - other files depend on it.
package funcs

import (
	"context"
	"text/template"
)

// Deps carries runtime dependencies available to function namespaces.
type Deps struct {
	Ctx          context.Context
	Data         DataProvider
	Templates    TemplateRenderer
	Experimental bool
}

// DataProvider is implemented by the core datasource registry.
type DataProvider interface {
	// Datasource reads and parses a datasource, optionally with extra
	// path arguments appended to the source URL.
	Datasource(alias string, args ...string) (interface{}, error)
	// Include reads a datasource and returns its raw content as a string.
	Include(alias string, args ...string) (string, error)
	// DefineDatasource defines a datasource at runtime; returns the alias.
	DefineDatasource(alias, rawurl string) (string, error)
	// DatasourceExists reports whether the alias is defined.
	DatasourceExists(alias string) bool
}

// TemplateRenderer renders nested/inline templates with the full function
// set available.
type TemplateRenderer interface {
	// RenderInline renders a template given as a string.
	RenderInline(name, text string, tctx interface{}) (string, error)
	// RenderPath renders template(s) loaded from a file or directory path.
	RenderPath(name, path string, tctx interface{}) (string, error)
	// RenderExec executes a previously-defined template by name.
	RenderExec(name string, tctx interface{}) (string, error)
}

// NSFactory creates the object backing a namespace. The returned object's
// exported methods become the namespace's functions.
type NSFactory func(deps *Deps) interface{}

var (
	namespaces = map[string]NSFactory{}
	globals    = template.FuncMap{}
)

// RegisterNS registers a namespace factory under a name, e.g. "strings".
func RegisterNS(name string, factory NSFactory) {
	if _, dup := namespaces[name]; dup {
		panic("duplicate namespace registration: " + name)
	}
	namespaces[name] = factory
}

// RegisterGlobal registers a top-level template function.
func RegisterGlobal(name string, fn interface{}) {
	if _, dup := globals[name]; dup {
		panic("duplicate global registration: " + name)
	}
	globals[name] = fn
}

// Build assembles the full template.FuncMap for one render.
func Build(deps *Deps) template.FuncMap {
	fm := template.FuncMap{}
	for name, f := range namespaces {
		factory := f
		fm[name] = func() interface{} { return factory(deps) }
	}
	for name, fn := range globals {
		fm[name] = fn
	}
	return fm
}

// Package dataparse holds the data-format parsers used both by datasource
// reading and by the data/conv function namespaces.
//
// YAML and TOML parsers are registered at init-time by the packages that
// implement them (internal/yaml, internal/toml) via RegisterYAML/RegisterTOML.
package dataparse

import (
	"bytes"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// YAML parses YAML into interface{} (map[string]interface{}, []interface{},
// string, int, float64, bool, nil). Registered by internal/yaml.
var YAML func([]byte) (interface{}, error)

// TOML parses TOML into interface{} (map[string]interface{}, []interface{},
// string, int64, float64, bool, time). Registered by internal/toml.
var TOML func([]byte) (interface{}, error)

// MarshalYAML serializes a value as YAML. Registered by internal/yaml.
var MarshalYAML func(interface{}) ([]byte, error)

// RegisterYAML installs the YAML parser/marshaler.
func RegisterYAML(parse func([]byte) (interface{}, error), marshal func(interface{}) ([]byte, error)) {
	YAML = parse
	MarshalYAML = marshal
}

// RegisterTOML installs the TOML parser.
func RegisterTOML(parse func([]byte) (interface{}, error)) {
	TOML = parse
}

// JSON parses JSON, decoding numbers as int64 when integral, float64
// otherwise.
func JSON(b []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber()
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	return convertJSONNumbers(v), nil
}

// JSONArray parses a JSON document that must contain an array.
func JSONArray(b []byte) ([]interface{}, error) {
	v, err := JSON(b)
	if err != nil {
		return nil, err
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, fmt.Errorf("expected JSON array, got %T", v)
	}
	return arr, nil
}

func convertJSONNumbers(v interface{}) interface{} {
	switch t := v.(type) {
	case map[string]interface{}:
		for k, e := range t {
			t[k] = convertJSONNumbers(e)
		}
		return t
	case []interface{}:
		for i, e := range t {
			t[i] = convertJSONNumbers(e)
		}
		return t
	case json.Number:
		if i, err := t.Int64(); err == nil {
			return i
		}
		if f, err := t.Float64(); err == nil {
			return f
		}
		return t.String()
	default:
		return v
	}
}

// CSV parses CSV content into a row-first 2D string array. delim of 0 means
// the default (comma).
func CSV(delim rune, b []byte) ([][]string, error) {
	r := csv.NewReader(bytes.NewReader(b))
	if delim != 0 {
		r.Comma = delim
	}
	return r.ReadAll()
}

// EnvFile parses a .env-style file into a map of key/value pairs.
func EnvFile(b []byte) (map[string]string, error) {
	out := map[string]string{}
	src := strings.ReplaceAll(string(b), "\r\n", "\n")
	for len(src) > 0 {
		var line string
		if i := strings.IndexByte(src, '\n'); i >= 0 {
			line, src = src[:i], src[i+1:]
		} else {
			line, src = src, ""
		}
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		line = strings.TrimPrefix(line, "export ")
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("can't separate key from value: %s", line)
		}
		key := strings.TrimSpace(k)
		v = strings.TrimSpace(v)
		if len(v) >= 2 && v[0] == '"' && v[len(v)-1] == '"' {
			v = unescapeDoubleQuoted(v[1 : len(v)-1])
		} else if len(v) >= 2 && v[0] == '\'' && v[len(v)-1] == '\'' {
			v = v[1 : len(v)-1]
		}
		// variable expansion for ${VAR} and $VAR from earlier keys and OS env
		v = expandEnvVars(v, out)
		out[key] = v
	}
	return out, nil
}

func unescapeDoubleQuoted(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '\\':
				sb.WriteByte('\\')
			case '"':
				sb.WriteByte('"')
			default:
				sb.WriteByte('\\')
				sb.WriteByte(s[i])
			}
			continue
		}
		sb.WriteByte(s[i])
	}
	return sb.String()
}

func expandEnvVars(s string, local map[string]string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '$' && i+1 < len(s) {
			if s[i+1] == '{' {
				if j := strings.IndexByte(s[i:], '}'); j > 0 {
					name := s[i+2 : i+j]
					if v, ok := local[name]; ok {
						sb.WriteString(v)
					}
					i += j
					continue
				}
			}
		}
		sb.WriteByte(s[i])
	}
	return sb.String()
}

// ReadAllString reads all of r as a string.
func ReadAllString(r io.Reader) (string, error) {
	b, err := io.ReadAll(r)
	return string(b), err
}

package cli

import (
	"fmt"
	"io"
	"os"
	"strings"
	"time"
)

// logger renders log lines in one of the GOMPLATE_LOG_FORMAT formats.
type logger struct {
	w       io.Writer
	format  string // json, logfmt, console, simple
	verbose bool
}

func newLogger(w io.Writer) *logger {
	format := os.Getenv("GOMPLATE_LOG_FORMAT")
	switch format {
	case "json", "logfmt", "console", "simple":
	default:
		format = "json" // non-interactive default
	}
	return &logger{w: w, format: format}
}

func (l *logger) log(level, msg string, attrs ...interface{}) {
	now := time.Now()
	var sb strings.Builder
	renderAttrs := func(quoteAll bool) {
		for i := 0; i+1 < len(attrs); i += 2 {
			k := fmt.Sprint(attrs[i])
			v := attrs[i+1]
			s, isStr := v.(string)
			if isStr || quoteAll {
				sb.WriteString(fmt.Sprintf("%s=%q", k, fmt.Sprint(v)))
			} else {
				sb.WriteString(fmt.Sprintf("%s=%v", k, v))
			}
			if i+2 < len(attrs) {
				sb.WriteByte(' ')
			}
		}
	}
	switch l.format {
	case "json":
		// {"time":"...","level":"ERROR","msg":"","err":"..."}
		lvl := map[string]string{"ERROR": "ERROR", "WARN": "WARN", "INFO": "INFO", "DEBUG": "DEBUG"}[level]
		fmt.Fprintf(&sb, `{"time":%q,"level":%q,"msg":%q`, now.Format(time.RFC3339Nano), lvl, msg)
		for i := 0; i+1 < len(attrs); i += 2 {
			fmt.Fprintf(&sb, ",%q:%q", fmt.Sprint(attrs[i]), fmt.Sprint(attrs[i+1]))
		}
		sb.WriteByte('}')
	case "logfmt":
		fmt.Fprintf(&sb, "time=%s level=%s msg=%q ", now.Format("2006-01-02T15:04:05.000Z07:00"), level, msg)
		renderAttrs(false)
	case "console":
		short := map[string]string{"ERROR": "ERR", "WARN": "WRN", "INFO": "INF", "DEBUG": "DBG"}[level]
		fmt.Fprintf(&sb, "%s %s %s ", now.Format("15:04:05"), short, msg)
		renderAttrs(false)
	case "simple":
		fmt.Fprintf(&sb, "  %s ", msg)
		renderAttrs(false)
	}
	fmt.Fprintln(l.w, sb.String())
}

func (l *logger) Error(err error) {
	l.log("ERROR", "", "err", err.Error())
}

func (l *logger) ErrorMsg(msg string) {
	l.log("ERROR", "", "err", msg)
}

func (l *logger) Debug(msg string, attrs ...interface{}) {
	if l.verbose {
		l.log("DEBUG", msg, attrs...)
	}
}

func (l *logger) Info(msg string, attrs ...interface{}) {
	if l.verbose {
		l.log("INFO", msg, attrs...)
	}
}

package cli

import (
	"fmt"
	"strings"
)

type flagKind int

const (
	kindString flagKind = iota
	kindBool
	kindStringSlice // comma-separated, accumulated over repetitions
)

type flagDef struct {
	name      string
	shorthand byte
	kind      flagKind
}

var flagDefs = []flagDef{
	{"datasource", 'd', kindStringSlice},
	{"datasource-header", 'H', kindStringSlice},
	{"context", 'c', kindStringSlice},
	{"plugin", 0, kindStringSlice},
	{"file", 'f', kindStringSlice},
	{"in", 'i', kindString},
	{"input-dir", 0, kindString},
	{"exclude", 0, kindStringSlice},
	{"exclude-processing", 0, kindStringSlice},
	{"include", 0, kindStringSlice},
	{"out", 'o', kindStringSlice},
	{"template", 't', kindStringSlice},
	{"output-dir", 0, kindString},
	{"output-map", 0, kindString},
	{"chmod", 0, kindString},
	{"exec-pipe", 0, kindBool},
	{"left-delim", 0, kindString},
	{"right-delim", 0, kindString},
	{"missing-key", 0, kindString},
	{"experimental", 0, kindBool},
	{"verbose", 'V', kindBool},
	{"config", 0, kindString},
	{"help", 'h', kindBool},
	{"version", 'v', kindBool},
}

// flagValues holds parsed flag results.
type flagValues struct {
	strings map[string]string
	bools   map[string]bool
	slices  map[string][]string
	changed map[string]bool
}

func newFlagValues() *flagValues {
	return &flagValues{
		strings: map[string]string{},
		bools:   map[string]bool{},
		slices:  map[string][]string{},
		changed: map[string]bool{},
	}
}

func defByName(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].name == name {
			return &flagDefs[i]
		}
	}
	return nil
}

func defByShorthand(c byte) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].shorthand == c && c != 0 {
			return &flagDefs[i]
		}
	}
	return nil
}

func (fv *flagValues) set(def *flagDef, val string) {
	fv.changed[def.name] = true
	switch def.kind {
	case kindString:
		fv.strings[def.name] = val
	case kindBool:
		fv.bools[def.name] = val == "true"
	case kindStringSlice:
		// pflag StringSlice splits on commas (CSV-style)
		parts := splitCSV(val)
		fv.slices[def.name] = append(fv.slices[def.name], parts...)
	}
}

// splitCSV splits a string on commas, honoring double-quoted sections
// (pflag stringSlice semantics).
func splitCSV(val string) []string {
	if val == "" {
		return []string{}
	}
	var out []string
	var sb strings.Builder
	inQuote := false
	for i := 0; i < len(val); i++ {
		c := val[i]
		switch {
		case c == '"':
			inQuote = !inQuote
		case c == ',' && !inQuote:
			out = append(out, sb.String())
			sb.Reset()
		default:
			sb.WriteByte(c)
		}
	}
	out = append(out, sb.String())
	return out
}

// parseFlags parses args (without argv[0]). Returns flag values, remaining
// positional args (after --), and error.
func parseFlags(args []string) (*flagValues, []string, error) {
	fv := newFlagValues()
	var postExec []string
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "--":
			postExec = args[i+1:]
			i = len(args)
		case strings.HasPrefix(a, "--"):
			name := a[2:]
			var val string
			hasVal := false
			if eq := strings.IndexByte(name, '='); eq >= 0 {
				name, val, hasVal = name[:eq], name[eq+1:], true
			}
			def := defByName(name)
			if def == nil {
				return nil, nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if def.kind == kindBool {
				if !hasVal {
					val = "true"
				}
				switch val {
				case "true", "false":
				default:
					return nil, nil, fmt.Errorf(`invalid argument %q for "--%s" flag: strconv.ParseBool: parsing %q: invalid syntax`, val, name, val)
				}
			} else if !hasVal {
				if i+1 >= len(args) {
					return nil, nil, fmt.Errorf("flag needs an argument: --%s", name)
				}
				i++
				val = args[i]
			}
			fv.set(def, val)
		case strings.HasPrefix(a, "-") && a != "-":
			cluster := a[1:]
			for len(cluster) > 0 {
				c := cluster[0]
				def := defByShorthand(c)
				if def == nil {
					return nil, nil, fmt.Errorf("unknown shorthand flag: %q in -%s", c, cluster)
				}
				cluster = cluster[1:]
				if def.kind == kindBool {
					fv.set(def, "true")
					continue
				}
				// needs a value: rest of cluster, or =value, or next arg
				var val string
				switch {
				case len(cluster) > 0 && cluster[0] == '=':
					val = cluster[1:]
					cluster = ""
				case len(cluster) > 0:
					val = cluster
					cluster = ""
				default:
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("flag needs an argument: %q in -%s", c, a[1:])
					}
					i++
					val = args[i]
				}
				fv.set(def, val)
			}
		default:
			return nil, nil, fmt.Errorf("unknown command %q for \"gomplate\"", a)
		}
		i++
	}
	return fv, postExec, nil
}

// Package data implements datasource registration and reading.
package data

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"

	"github.com/reimpl/gomplate/internal/dataparse"
)

// Source is a single registered datasource.
type Source struct {
	Alias  string
	URL    *url.URL
	Header http.Header
}

// Registry holds all defined datasources.
type Registry struct {
	mu       sync.Mutex
	sources  map[string]*Source
	headers  map[string]http.Header
	stdin    io.Reader
	stdinBuf []byte
	client   *http.Client
	cache    map[string]interface{}
}

func NewRegistry(stdin io.Reader) *Registry {
	return &Registry{
		sources: map[string]*Source{},
		headers: map[string]http.Header{},
		stdin:   stdin,
		client:  &http.Client{},
		cache:   map[string]interface{}{},
	}
}

// Define parses a datasource definition of the form "alias=URL", "alias=",
// or a bare URL (alias inferred). Returns the alias.
func (r *Registry) Define(def string) (string, error) {
	return r.DefineWithHeader(def, nil)
}

func (r *Registry) DefineWithHeader(def string, header http.Header) (string, error) {
	alias, rawurl, ok := strings.Cut(def, "=")
	if !ok {
		// no '=' - the whole thing is a URL; infer alias
		rawurl = def
		alias = ""
	}
	if alias == "" {
		alias = inferAlias(rawurl)
		if alias == "" {
			return "", fmt.Errorf("could not infer datasource alias from %q", def)
		}
	}
	u, err := parseSourceURL(rawurl)
	if err != nil {
		return "", fmt.Errorf("invalid datasource URL %q: %v", rawurl, err)
	}
	if old, dup := r.sources[alias]; dup {
		_ = old
		// later definitions override earlier ones
	}
	r.sources[alias] = &Source{Alias: alias, URL: u, Header: header}
	return alias, nil
}

// DefineURL defines a datasource from an already-split alias and URL string.
func (r *Registry) DefineURL(alias, rawurl string, header http.Header) error {
	u, err := parseSourceURL(rawurl)
	if err != nil {
		return fmt.Errorf("invalid datasource URL %q: %v", rawurl, err)
	}
	r.sources[alias] = &Source{Alias: alias, URL: u, Header: header}
	return nil
}

func inferAlias(rawurl string) string {
	// only for plain relative filenames in the current directory
	if strings.ContainsAny(rawurl, "/:") {
		return ""
	}
	base := filepath.Base(rawurl)
	ext := filepath.Ext(base)
	return strings.TrimSuffix(base, ext)
}

func parseSourceURL(rawurl string) (*url.URL, error) {
	if rawurl == "" {
		return &url.URL{}, nil
	}
	u, err := url.Parse(rawurl)
	if err != nil {
		return nil, err
	}
	// bare relative paths (no scheme) are file URLs
	if u.Scheme == "" {
		u = &url.URL{Scheme: "file", Path: rawurl}
		if strings.HasPrefix(rawurl, "/") {
			u = &url.URL{Scheme: "file", Path: rawurl}
		}
	}
	return u, nil
}

// AddExtraHeader records headers to send for the given datasource alias.
func (r *Registry) AddExtraHeader(alias string, h http.Header) {
	r.headers[alias] = h
}

// Exists reports whether a datasource alias is defined.
func (r *Registry) Exists(alias string) bool {
	_, ok := r.sources[alias]
	return ok
}

// Aliases returns sorted defined aliases.
func (r *Registry) Aliases() []string {
	out := make([]string, 0, len(r.sources))
	for a := range r.sources {
		out = append(out, a)
	}
	sort.Strings(out)
	return out
}

// Get returns the source for an alias.
func (r *Registry) Get(alias string) (*Source, bool) {
	s, ok := r.sources[alias]
	return s, ok
}

func (r *Registry) lookup(alias string) (*Source, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	s, ok := r.sources[alias]
	if !ok {
		return nil, fmt.Errorf("undefined datasource '%s'", alias)
	}
	return s, nil
}

// subPath appends extra path args to the source URL.
func subPath(u *url.URL, args ...string) *url.URL {
	v := *u
	if len(args) > 0 && args[0] != "" {
		p := strings.Join(args, "/")
		base := v.Path
		if v.Opaque != "" {
			base = v.Opaque
		}
		if strings.HasSuffix(base, "/") {
			base += p
		} else if base == "" {
			base = p
		} else {
			base += "/" + p
		}
		if v.Opaque != "" {
			v.Opaque = base
		} else {
			v.Path = base
		}
	}
	return &v
}

// Datasource reads and parses a datasource.
func (r *Registry) Datasource(ctx context.Context, alias string, args ...string) (interface{}, error) {
	s, err := r.lookup(alias)
	if err != nil {
		return nil, err
	}
	u := subPath(s.URL, args...)
	key := alias + "|" + u.String()
	if v, ok := r.cache[key]; ok {
		return v, nil
	}
	v, err := r.read(ctx, s, u, false)
	if err != nil {
		return nil, err
	}
	r.cache[key] = v
	return v, nil
}

// Include reads a datasource and returns raw string content.
func (r *Registry) Include(ctx context.Context, alias string, args ...string) (string, error) {
	s, err := r.lookup(alias)
	if err != nil {
		return "", err
	}
	u := subPath(s.URL, args...)
	v, err := r.read(ctx, s, u, true)
	if err != nil {
		return "", err
	}
	return v.(string), nil
}

// read fetches content. If raw is true, returns the content as string.
func (r *Registry) read(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
	scheme := u.Scheme
	switch scheme {
	case "file", "":
		return r.readFile(u, raw)
	case "stdin":
		return r.readStdin(u, raw)
	case "env":
		return r.readEnv(u, raw)
	case "http", "https":
		return r.readHTTP(ctx, s, u, raw)
	case "merge":
		return r.readMerge(ctx, s, u, raw)
	default:
		return nil, fmt.Errorf("datasources with scheme %q are not supported", scheme)
	}
}

func mimeOverride(u *url.URL) string {
	param := os.Getenv("GOMPLATE_TYPE_PARAM")
	if param == "" {
		param = "type"
	}
	q := u.Query()
	t := q.Get(param)
	if i := strings.IndexByte(t, ';'); i >= 0 {
		t = strings.TrimSpace(t[:i])
	}
	return t
}

var extMimes = map[string]string{
	".json": "application/json",
	".yml":  "application/yaml",
	".yaml": "application/yaml",
	".toml": "application/toml",
	".csv":  "text/csv",
	".env":  "application/x-env",
}

func mimeFor(u *url.URL, httpMime string) string {
	if t := mimeOverride(u); t != "" {
		return t
	}
	if httpMime != "" {
		if i := strings.IndexByte(httpMime, ';'); i >= 0 {
			httpMime = strings.TrimSpace(httpMime[:i])
		}
		if m, ok := extMimes[strings.ToLower(filepath.Ext(u.Path))]; ok && httpMime == "text/plain" {
			return m
		}
		return httpMime
	}
	ext := strings.ToLower(filepath.Ext(u.Path))
	if m, ok := extMimes[ext]; ok {
		return m
	}
	return "text/plain"
}

// parseContent parses bytes per MIME type.
func parseContent(mime string, b []byte) (interface{}, error) {
	switch mime {
	case "application/json":
		return dataparse.JSON(b)
	case "application/array+json":
		return dataparse.JSONArray(b)
	case "application/yaml", "application/x-yaml", "text/yaml":
		if dataparse.YAML == nil {
			return nil, fmt.Errorf("YAML support unavailable")
		}
		return dataparse.YAML(b)
	case "application/toml":
		if dataparse.TOML == nil {
			return nil, fmt.Errorf("TOML support unavailable")
		}
		return dataparse.TOML(b)
	case "text/csv":
		return dataparse.CSV(0, b)
	case "application/x-env":
		return dataparse.EnvFile(b)
	case "text/plain", "application/octet-stream", "":
		return string(b), nil
	default:
		return nil, fmt.Errorf("unsupported MIME type: %s", mime)
	}
}

func (r *Registry) readFile(u *url.URL, raw bool) (interface{}, error) {
	path := u.Path
	if u.Host != "" && u.Host != "." {
		path = u.Host + u.Path
	}
	if strings.HasSuffix(u.Path, "/") {
		entries, err := os.ReadDir(path)
		if err != nil {
			return nil, err
		}
		names := []string{}
		for _, e := range entries {
			names = append(names, e.Name())
		}
		return names, nil
	}
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if raw {
		return string(b), nil
	}
	return parseContent(mimeFor(u, ""), b)
}

func (r *Registry) readStdin(u *url.URL, raw bool) (interface{}, error) {
	r.mu.Lock()
	if r.stdinBuf == nil {
		b, err := io.ReadAll(r.stdin)
		if err != nil {
			r.mu.Unlock()
			return nil, err
		}
		r.stdinBuf = b
	}
	b := r.stdinBuf
	r.mu.Unlock()
	if raw {
		return string(b), nil
	}
	return parseContent(mimeFor(u, ""), b)
}

func (r *Registry) readEnv(u *url.URL, raw bool) (interface{}, error) {
	name := u.Opaque
	if name == "" {
		name = strings.TrimLeft(u.Path, "/")
	}
	val := os.Getenv(name)
	if raw {
		return val, nil
	}
	return parseContent(mimeFor(u, ""), []byte(val))
}

func (r *Registry) readHTTP(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "Go-http-client/1.1")
	for k, vs := range s.Header {
		for _, v := range vs {
			req.Header.Set(k, v)
		}
	}
	if h, ok := r.headers[s.Alias]; ok {
		for k, vs := range h {
			for _, v := range vs {
				req.Header.Set(k, v)
			}
		}
	}
	resp, err := r.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, fmt.Errorf("unexpected HTTP status %d from %s", resp.StatusCode, u.String())
	}
	if raw {
		return string(b), nil
	}
	return parseContent(mimeFor(u, resp.Header.Get("Content-Type")), b)
}

func (r *Registry) readMerge(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
	parts := strings.Split(u.Opaque, "|")
	if len(parts) < 2 {
		return nil, fmt.Errorf("merge: requires at least two datasources")
	}
	var merged map[string]interface{}
	// merge right to left
	for i := len(parts) - 1; i >= 0; i-- {
		p := parts[i]
		var v interface{}
		var err error
		if r.Exists(p) {
			v, err = r.Datasource(ctx, p)
		} else {
			tmp := &Source{Alias: p}
			tu, terr := parseSourceURL(p)
			if terr != nil {
				return nil, terr
			}
			v, err = r.read(ctx, tmp, tu, false)
		}
		if err != nil {
			return nil, err
		}
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("merge: datasource %q is not a map", p)
		}
		merged = deepMerge(m, merged)
	}
	return merged, nil
}

// deepMerge overlays src onto dst (src wins), merging nested maps.
func deepMerge(src, dst map[string]interface{}) map[string]interface{} {
	if dst == nil {
		dst = map[string]interface{}{}
	}
	for k, v := range src {
		if sm, ok := v.(map[string]interface{}); ok {
			if dm, ok := dst[k].(map[string]interface{}); ok {
				dst[k] = deepMerge(sm, dm)
				continue
			}
		}
		dst[k] = v
	}
	return dst
}

