package cli

import (
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/reimpl/gomplate/internal/dataparse"
)

// sourceConf is a datasource/template config entry.
type sourceConf struct {
	URL    string
	Header http.Header
}

// pluginConf configures a plugin command.
type pluginConf struct {
	Cmd     string
	Args    []string
	Pipe    bool
	Timeout time.Duration
}

// config is the merged runtime configuration.
type config struct {
	Input             string
	InputFiles        []string
	InputDir          string
	OutputFiles       []string
	OutputDir         string
	OutputMap         string
	Excludes          []string
	ExcludeProcessing []string
	Includes          []string
	Datasources       map[string]sourceConf
	Context           map[string]sourceConf
	Templates         map[string]sourceConf
	Plugins           map[string]pluginConf
	PluginTimeout     time.Duration
	LeftDelim         string
	RightDelim        string
	MissingKey        string
	Chmod             string
	ExecPipe          bool
	Experimental      bool
	Verbose           bool
	PostExec          []string
}

func defaultConfig() *config {
	return &config{
		InputFiles:    []string{"-"},
		OutputFiles:   []string{"-"},
		OutputDir:     ".",
		Datasources:   map[string]sourceConf{},
		Context:       map[string]sourceConf{},
		Templates:     map[string]sourceConf{},
		Plugins:       map[string]pluginConf{},
		PluginTimeout: 5 * time.Second,
		LeftDelim:     "{{",
		RightDelim:    "}}",
		MissingKey:    "error",
	}
}

// applyEnv applies environment-variable based settings.
func (c *config) applyEnv() {
	if v, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok {
		c.LeftDelim = v
	}
	if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok {
		c.RightDelim = v
	}
	if v := os.Getenv("GOMPLATE_EXPERIMENTAL"); v != "" {
		c.Experimental = v == "true" || v == "1"
	}
	if v := os.Getenv("GOMPLATE_PLUGIN_TIMEOUT"); v != "" {
		if d, err := time.ParseDuration(v); err == nil {
			c.PluginTimeout = d
		}
	}
}

// asMap converts parsed YAML config into our config struct.
func (c *config) applyMap(m map[string]interface{}) error {
	str := func(key string, set func(string)) {
		if v, ok := m[key]; ok {
			set(fmt.Sprintf("%v", v))
		}
	}
	strSlice := func(key string, set func([]string)) {
		if v, ok := m[key]; ok {
			switch t := v.(type) {
			case []interface{}:
				out := make([]string, 0, len(t))
				for _, e := range t {
					out = append(out, fmt.Sprintf("%v", e))
				}
				set(out)
			case string:
				set([]string{t})
			}
		}
	}
	boolOpt := func(key string, set func(bool)) {
		if v, ok := m[key]; ok {
			if b, ok := v.(bool); ok {
				set(b)
			}
		}
	}
	srcMap := func(key string, set func(map[string]sourceConf)) {
		v, ok := m[key]
		if !ok {
			return
		}
		mm, ok := v.(map[string]interface{})
		if !ok {
			return
		}
		out := map[string]sourceConf{}
		for alias, e := range mm {
			em, ok := e.(map[string]interface{})
			if !ok {
				continue
			}
			sc := sourceConf{}
			if u, ok := em["url"]; ok {
				sc.URL = fmt.Sprintf("%v", u)
			}
			if h, ok := em["header"].(map[string]interface{}); ok {
				sc.Header = http.Header{}
				for hk, hv := range h {
					switch t := hv.(type) {
					case []interface{}:
						for _, e := range t {
							sc.Header.Add(hk, fmt.Sprintf("%v", e))
						}
					case string:
						sc.Header.Add(hk, t)
					}
				}
			}
			out[alias] = sc
		}
		set(out)
	}

	str("in", func(s string) { c.Input = s })
	strSlice("inputFiles", func(s []string) { c.InputFiles = s })
	str("inputDir", func(s string) { c.InputDir = s })
	strSlice("outputFiles", func(s []string) { c.OutputFiles = s })
	str("outputDir", func(s string) { c.OutputDir = s })
	str("outputMap", func(s string) { c.OutputMap = s })
	strSlice("excludes", func(s []string) { c.Excludes = s })
	strSlice("excludeProcessing", func(s []string) { c.ExcludeProcessing = s })
	strSlice("includes", func(s []string) { c.Includes = s })
	str("leftDelim", func(s string) { c.LeftDelim = s })
	str("rightDelim", func(s string) { c.RightDelim = s })
	str("missingKey", func(s string) { c.MissingKey = s })
	boolOpt("execPipe", func(b bool) { c.ExecPipe = b })
	boolOpt("experimental", func(b bool) { c.Experimental = b })
	if v, ok := m["chmod"]; ok {
		c.Chmod = fmt.Sprintf("%v", v)
	}
	strSlice("postExec", func(s []string) { c.PostExec = s })
	if v, ok := m["pluginTimeout"]; ok {
		if d, err := time.ParseDuration(fmt.Sprintf("%v", v)); err == nil {
			c.PluginTimeout = d
		}
	}
	srcMap("datasources", func(x map[string]sourceConf) { c.Datasources = x })
	srcMap("context", func(x map[string]sourceConf) { c.Context = x })
	srcMap("templates", func(x map[string]sourceConf) { c.Templates = x })

	if v, ok := m["plugins"]; ok {
		if mm, ok := v.(map[string]interface{}); ok {
			for name, e := range mm {
				pc := pluginConf{}
				switch t := e.(type) {
				case string:
					pc.Cmd = t
				case map[string]interface{}:
					if cmd, ok := t["cmd"]; ok {
						pc.Cmd = fmt.Sprintf("%v", cmd)
					}
					if args, ok := t["args"].([]interface{}); ok {
						for _, a := range args {
							pc.Args = append(pc.Args, fmt.Sprintf("%v", a))
						}
					}
					if p, ok := t["pipe"].(bool); ok {
						pc.Pipe = p
					}
					if to, ok := t["timeout"]; ok {
						if d, err := time.ParseDuration(fmt.Sprintf("%v", to)); err == nil {
							pc.Timeout = d
						}
					}
				}
				c.Plugins[name] = pc
			}
		}
	}
	return nil
}

// applyFlags overlays command-line flag values.
func (c *config) applyFlags(fv *flagValues) {
	ch := fv.changed
	if ch["in"] {
		c.Input = fv.strings["in"]
	}
	if ch["file"] {
		c.InputFiles = fv.slices["file"]
	}
	if ch["input-dir"] {
		c.InputDir = fv.strings["input-dir"]
	}
	if ch["out"] {
		c.OutputFiles = fv.slices["out"]
	}
	if ch["output-dir"] {
		c.OutputDir = fv.strings["output-dir"]
	}
	if ch["output-map"] {
		c.OutputMap = fv.strings["output-map"]
	}
	if ch["exclude"] {
		c.Excludes = fv.slices["exclude"]
	}
	if ch["exclude-processing"] {
		c.ExcludeProcessing = fv.slices["exclude-processing"]
	}
	if ch["include"] {
		c.Includes = fv.slices["include"]
	}
	if ch["left-delim"] {
		c.LeftDelim = fv.strings["left-delim"]
	}
	if ch["right-delim"] {
		c.RightDelim = fv.strings["right-delim"]
	}
	if ch["missing-key"] {
		c.MissingKey = fv.strings["missing-key"]
	}
	if ch["chmod"] {
		c.Chmod = fv.strings["chmod"]
	}
	if ch["exec-pipe"] {
		c.ExecPipe = fv.bools["exec-pipe"]
	}
	if ch["experimental"] {
		c.Experimental = fv.bools["experimental"]
	}
	if ch["verbose"] {
		c.Verbose = fv.bools["verbose"]
	}
	for _, d := range fv.slices["datasource"] {
		alias, rawurl, _ := strings.Cut(d, "=")
		if rawurl == "" {
			rawurl = alias
			alias = ""
		}
		sc := c.Datasources[alias]
		sc.URL = rawurl
		c.Datasources[alias] = sc
	}
	for _, d := range fv.slices["context"] {
		alias, rawurl, _ := strings.Cut(d, "=")
		if rawurl == "" {
			rawurl = alias
			alias = ""
		}
		sc := c.Context[alias]
		sc.URL = rawurl
		c.Context[alias] = sc
	}
	for _, d := range fv.slices["template"] {
		alias, rawurl, _ := strings.Cut(d, "=")
		if rawurl == "" {
			rawurl = alias
			alias = ""
		}
		sc := c.Templates[alias]
		sc.URL = rawurl
		c.Templates[alias] = sc
	}
	for _, d := range fv.slices["plugin"] {
		name, path, _ := strings.Cut(d, "=")
		c.Plugins[name] = pluginConf{Cmd: path}
	}
	for _, d := range fv.slices["datasource-header"] {
		alias, hdr, _ := strings.Cut(d, "=")
		name, val, _ := strings.Cut(hdr, ":")
		sc := c.Datasources[alias]
		if sc.Header == nil {
			sc.Header = http.Header{}
		}
		sc.Header.Add(strings.TrimSpace(name), strings.TrimSpace(val))
		c.Datasources[alias] = sc
	}
}

// validate checks config consistency.
func (c *config) validate() error {
	nIn := len(c.InputFiles)
	if c.Input != "" {
		nIn = 1
	}
	if c.InputDir != "" {
		nIn = 0
	}
	if c.InputDir == "" && len(c.OutputFiles) != nIn {
		return fmt.Errorf(`must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options
---
%s`, len(c.OutputFiles), nIn, c.dump())
	}
	if c.InputDir != "" && c.Input != "" {
		return fmt.Errorf("only one of 'inputDir' and 'in' can be provided")
	}
	return nil
}

// dump renders a short YAML-ish dump used in validation error messages.
func (c *config) dump() string {
	var sb strings.Builder
	if c.Input != "" {
		fmt.Fprintf(&sb, "in: '%s'\n", c.Input)
	}
	if len(c.InputFiles) > 0 && !(len(c.InputFiles) == 1 && c.InputFiles[0] == "-") {
		fmt.Fprintf(&sb, "inputFiles: [%s]\n", strings.Join(c.InputFiles, ", "))
	}
	if c.InputDir != "" {
		fmt.Fprintf(&sb, "inputDir: %s\n", c.InputDir)
	}
	if len(c.OutputFiles) > 0 && !(len(c.OutputFiles) == 1 && c.OutputFiles[0] == "-") {
		fmt.Fprintf(&sb, "outputFiles: [%s]\n", strings.Join(c.OutputFiles, ", "))
	}
	if c.OutputDir != "" && c.OutputDir != "." {
		fmt.Fprintf(&sb, "outputDir: %s\n", c.OutputDir)
	}
	if c.OutputMap != "" {
		fmt.Fprintf(&sb, "outputMap: '%s'\n", c.OutputMap)
	}
	fmt.Fprintf(&sb, "leftDelim: '%s'\n", c.LeftDelim)
	fmt.Fprintf(&sb, "rightDelim: '%s'\n", c.RightDelim)
	fmt.Fprintf(&sb, "missingKey: %s\n", c.MissingKey)
	fmt.Fprintf(&sb, "pluginTimeout: %s\n", c.PluginTimeout)
	return sb.String()
}

package cli

import (
	"bytes"
	"context"
	_ "embed"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"text/template"
	"time"

	"github.com/reimpl/gomplate/internal/data"
	"github.com/reimpl/gomplate/internal/dataparse"
	"github.com/reimpl/gomplate/internal/funcs"

	_ "github.com/reimpl/gomplate/internal/toml"
	_ "github.com/reimpl/gomplate/internal/yaml"
)

//go:embed helptext.txt
var helpText string

// usageText is the help text without the leading description line.
var usageText = strings.TrimPrefix(helpText, "Process text files with Go templates\n\n")

const versionString = "gomplate version 0.0.0"

// Run executes gomplate. Returns the exit code.
func Run(args []string, stdin io.Reader, stdout, stderr *os.File) int {
	log := newLogger(stderr)

	fv, postExec, err := parseFlags(args)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %s\n", err)
		fmt.Fprint(stdout, usageText)
		log.ErrorMsg(err.Error())
		return 1
	}
	if fv.bools["help"] {
		fmt.Fprint(stdout, helpText)
		return 0
	}
	if fv.bools["version"] {
		fmt.Fprintln(stdout, versionString)
		return 0
	}

	cfg, cerr := loadConfig(fv, postExec)
	if cerr != nil {
		log.Error(cerr)
		return 1
	}
	log.verbose = cfg.Verbose

	if err := cfg.validate(); err != nil {
		log.ErrorMsg("failed to validate config: " + err.Error())
		return 1
	}

	r := &renderer{
		cfg:     cfg,
		sources: data.NewRegistry(stdin),
		stdin:   stdin,
		stdout:  stdout,
		stderr:  stderr,
		log:     log,
	}

	// register datasources
	for alias, sc := range cfg.Datasources {
		if alias == "" {
			if _, err := r.sources.DefineWithHeader(sc.URL, sc.Header); err != nil {
				log.Error(err)
				return 1
			}
			continue
		}
		if err := r.sources.DefineURL(alias, sc.URL, sc.Header); err != nil {
			log.Error(err)
			return 1
		}
	}
	for alias, sc := range cfg.Context {
		if alias != "" {
			if err := r.sources.DefineURL(alias, sc.URL, sc.Header); err != nil {
				log.Error(err)
				return 1
			}
		}
	}

	r.deps = &funcs.Deps{
		Ctx:          context.Background(),
		Data:         &dataProvider{r: r},
		Experimental: cfg.Experimental,
	}
	r.deps.Templates = r

	// build the default context
	tctx, err := r.buildContext()
	if err != nil {
		log.Error(err)
		return 1
	}
	r.tctx = tctx

	templates, err := r.gatherTemplates()
	if err != nil {
		log.ErrorMsg("failed to gather templates for rendering: " + err.Error())
		return 1
	}

	var lastOutput bytes.Buffer
	for _, t := range templates {
		out, rerr := r.renderOne(t)
		if rerr != nil {
			log.ErrorMsg("renderTemplate: " + rerr.Error())
			return 1
		}
		lastOutput.Reset()
		lastOutput.Write(out)
		if cfg.ExecPipe {
			continue
		}
		if werr := r.writeOutput(t, out); werr != nil {
			log.Error(werr)
			return 1
		}
	}

	if len(cfg.PostExec) > 0 {
		if err := r.runPostExec(&lastOutput); err != nil {
			log.Error(err)
			return 1
		}
	}
	return 0
}

// loadConfig merges defaults, env, config file, and flags.
func loadConfig(fv *flagValues, postExec []string) (*config, error) {
	cfg := defaultConfig()
	cfg.applyEnv()

	cfgPath := fv.strings["config"]
	if !fv.changed["config"] {
		cfgPath = os.Getenv("GOMPLATE_CONFIG")
		if cfgPath == "" {
			if _, ok := os.LookupEnv("GOMPLATE_CONFIG"); !ok {
				cfgPath = ".gomplate.yaml"
			}
		}
	}
	if cfgPath != "" {
		b, err := os.ReadFile(cfgPath)
		switch {
		case err == nil:
			if dataparse.YAML == nil {
				return nil, fmt.Errorf("failed to read config file: YAML support unavailable")
			}
			v, err := dataparse.YAML(b)
			if err != nil {
				return nil, fmt.Errorf("failed to parse config file %s: %v", cfgPath, err)
			}
			if m, ok := v.(map[string]interface{}); ok {
				if err := cfg.applyMap(m); err != nil {
					return nil, fmt.Errorf("failed to parse config file %s: %v", cfgPath, err)
				}
			}
		case cfgPath != ".gomplate.yaml" || fv.changed["config"]:
			if !os.IsNotExist(err) {
				return nil, fmt.Errorf("failed to read config file %s: %v", cfgPath, err)
			}
			if fv.changed["config"] || os.Getenv("GOMPLATE_CONFIG") != "" {
				return nil, fmt.Errorf("failed to read config file %s: %v", cfgPath, err)
			}
		}
	}

	cfg.applyFlags(fv)
	if len(postExec) > 0 {
		cfg.PostExec = postExec
	}
	if cfg.Input != "" {
		cfg.InputFiles = nil
	}
	return cfg, nil
}

// renderer renders templates with the configured function set.
type renderer struct {
	cfg     *config
	sources *data.Registry
	deps    *funcs.Deps
	tctx    interface{}
	stdin   io.Reader
	stdout  io.Writer
	stderr  io.Writer
	log     *logger
}

// dataProvider adapts the source registry to funcs.DataProvider.
type dataProvider struct{ r *renderer }

func (p *dataProvider) Datasource(alias string, args ...string) (interface{}, error) {
	return p.r.sources.Datasource(p.r.deps.Ctx, alias, args...)
}
func (p *dataProvider) Include(alias string, args ...string) (string, error) {
	return p.r.sources.Include(p.r.deps.Ctx, alias, args...)
}
func (p *dataProvider) DefineDatasource(alias, rawurl string) (string, error) {
	if alias == "" {
		return p.r.sources.Define(rawurl)
	}
	return alias, p.r.sources.DefineURL(alias, rawurl, nil)
}
func (p *dataProvider) DatasourceExists(alias string) bool {
	return p.r.sources.Exists(alias)
}

// buildContext constructs the default template context.
func (r *renderer) buildContext() (interface{}, error) {
	env := map[string]string{}
	for _, e := range os.Environ() {
		k, v, _ := strings.Cut(e, "=")
		env[k] = v
	}
	var root map[string]interface{} = map[string]interface{}{"Env": env}

	// aliases in deterministic order: "." first
	aliases := make([]string, 0, len(r.cfg.Context))
	for a := range r.cfg.Context {
		aliases = append(aliases, a)
	}
	if i := indexOf(aliases, "."); i > 0 {
		aliases[0], aliases[i] = aliases[i], aliases[0]
	}
	for _, alias := range aliases {
		sc := r.cfg.Context[alias]
		v, err := r.sources.Datasource(r.deps.Ctx, alias)
		if err != nil {
			return nil, fmt.Errorf("failed to load context datasource %s (%s): %v", alias, sc.URL, err)
		}
		if alias == "." {
			if m, ok := v.(map[string]interface{}); ok {
				root = m
			} else {
				root = map[string]interface{}{"": v}
				return v, nil
			}
		} else {
			root[alias] = v
		}
	}
	return root, nil
}

func indexOf(s []string, v string) int {
	for i, e := range s {
		if e == v {
			return i
		}
	}
	return -1
}

// funcMap builds the template function map including plugins.
func (r *renderer) funcMap() template.FuncMap {
	fm := funcs.Build(r.deps)
	for name, pc := range r.cfg.Plugins {
		fm[name] = r.pluginFunc(pc)
	}
	return fm
}

func (r *renderer) newTemplate(name string) *template.Template {
	t := template.New(name)
	t.Option("missingkey=" + r.cfg.MissingKey)
	t.Delims(r.cfg.LeftDelim, r.cfg.RightDelim)
	t.Funcs(r.funcMap())
	return t
}

// parseNested adds --template templates to the template set.
func (r *renderer) parseNested(t *template.Template) error {
	for alias, sc := range r.cfg.Templates {
		path := sc.URL
		path = strings.TrimPrefix(path, "file://")
		fi, err := os.Stat(path)
		if err != nil {
			return fmt.Errorf("stat %q: %w", path, err)
		}
		if fi.IsDir() || strings.HasSuffix(sc.URL, "/") {
			entries, err := os.ReadDir(path)
			if err != nil {
				return err
			}
			for _, e := range entries {
				if e.IsDir() {
					continue
				}
				b, err := os.ReadFile(filepath.Join(path, e.Name()))
				if err != nil {
					return err
				}
				name := filepath.Join(alias, e.Name())
				if alias == "" {
					name = filepath.Join(path, e.Name())
				}
				if _, err := t.New(name).Parse(string(b)); err != nil {
					return fmt.Errorf("parse template %s: %w", name, err)
				}
			}
			continue
		}
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		name := alias
		if name == "" {
			name = sc.URL
		}
		if _, err := t.New(name).Parse(string(b)); err != nil {
			return fmt.Errorf("parse template %s: %w", name, err)
		}
	}
	return nil
}

// renderTemplate parses and executes one template text.
func (r *renderer) renderTemplate(name, text string, tctx interface{}) ([]byte, error) {
	t := r.newTemplate(name)
	if err := r.parseNested(t); err != nil {
		return nil, err
	}
	tmpl, err := t.Parse(text)
	if err != nil {
		return nil, fmt.Errorf("parse template %s: %w", name, err)
	}
	buf := &bytes.Buffer{}
	err = tmpl.ExecuteTemplate(buf, name, tctx)
	if err != nil {
		// partial output is still written for stdout outputs
		if buf.Len() > 0 {
			if w, ok := r.stdout.(*os.File); ok {
				buf.WriteTo(w)
			}
		}
		return nil, fmt.Errorf("failed to render template %s: %w", name, err)
	}
	return buf.Bytes(), nil
}

// RenderInline implements funcs.TemplateRenderer.
func (r *renderer) RenderInline(name, text string, tctx interface{}) (string, error) {
	t := r.newTemplate(name)
	tmpl, err := t.Parse(text)
	if err != nil {
		return "", fmt.Errorf("parse template %s: %w", name, err)
	}
	buf := &bytes.Buffer{}
	if err := tmpl.ExecuteTemplate(buf, name, tctx); err != nil {
		return "", fmt.Errorf("failed to render template %s: %w", name, err)
	}
	return buf.String(), nil
}

// RenderPath implements funcs.TemplateRenderer.
func (r *renderer) RenderPath(name, path string, tctx interface{}) (string, error) {
	fi, err := os.Stat(path)
	if err != nil {
		return "", fmt.Errorf("stat %q: %w", path, err)
	}
	t := r.newTemplate(name)
	execName := name
	if fi.IsDir() {
		entries, err := os.ReadDir(path)
		if err != nil {
			return "", err
		}
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			b, err := os.ReadFile(filepath.Join(path, e.Name()))
			if err != nil {
				return "", err
			}
			if _, err := t.New(e.Name()).Parse(string(b)); err != nil {
				return "", fmt.Errorf("parse template %s: %w", e.Name(), err)
			}
		}
		execName = filepath.Base(path)
	} else {
		b, err := os.ReadFile(path)
		if err != nil {
			return "", err
		}
		if _, err := t.Parse(string(b)); err != nil {
			return "", fmt.Errorf("parse template %s: %w", name, err)
		}
	}
	buf := &bytes.Buffer{}
	if err := t.ExecuteTemplate(buf, execName, tctx); err != nil {
		return "", fmt.Errorf("failed to render template %s: %w", name, err)
	}
	return buf.String(), nil
}

// RenderExec implements funcs.TemplateRenderer.
func (r *renderer) RenderExec(name string, tctx interface{}) (string, error) {
	t := r.newTemplate("tmpl.Exec")
	if err := r.parseNested(t); err != nil {
		return "", err
	}
	buf := &bytes.Buffer{}
	if err := t.ExecuteTemplate(buf, name, tctx); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// tmplInput is one template to render plus its output target.
type tmplInput struct {
	name string // template name (also used in error messages)
	text string
	out  string // output path or "-"
	mode os.FileMode
}

// gatherTemplates computes the list of templates to render.
func (r *renderer) gatherTemplates() ([]tmplInput, error) {
	cfg := r.cfg
	switch {
	case cfg.Input != "":
		out := "-"
		if len(cfg.OutputFiles) > 0 && cfg.OutputFiles[0] != "" {
			out = cfg.OutputFiles[0]
		}
		return []tmplInput{{name: "<arg>", text: cfg.Input, out: out, mode: 0o644}}, nil

	case cfg.InputDir != "":
		return r.gatherDir()

	default:
		inputs := cfg.InputFiles
		if len(inputs) == 0 {
			inputs = []string{"-"}
		}
		outs := cfg.OutputFiles
		if len(outs) == 0 {
			outs = []string{"-"}
		}
		var stdinText string
		var stdinErr error
		var stdinOnce bool
		out := make([]tmplInput, 0, len(inputs))
		for i, in := range inputs {
			o := "-"
			if i < len(outs) {
				o = outs[i]
			}
			if in == "-" {
				if !stdinOnce {
					b, err := io.ReadAll(r.stdin)
					stdinText, stdinErr, stdinOnce = string(b), err, true
				}
				if stdinErr != nil {
					return nil, stdinErr
				}
				out = append(out, tmplInput{name: "-", text: stdinText, out: o, mode: 0o644})
				continue
			}
			fi, err := os.Stat(in)
			if err != nil {
				return nil, fmt.Errorf("fileToTemplate: stat %q: %w", in, err)
			}
			b, err := os.ReadFile(in)
			if err != nil {
				return nil, fmt.Errorf("fileToTemplate: %w", err)
			}
			out = append(out, tmplInput{name: in, text: string(b), out: o, mode: fi.Mode()})
		}
		return out, nil
	}
}

// gatherDir handles --input-dir mode.
func (r *renderer) gatherDir() ([]tmplInput, error) {
	cfg := r.cfg
	root := cfg.InputDir
	var out []tmplInput
	ignores, err := loadGomplateIgnores(root)
	if err != nil {
		return nil, err
	}
	err = filepath.Walk(root, func(path string, fi os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		if fi.IsDir() {
			return nil
		}
		if matchPatterns(ignores, rel) || matchPatterns(cfg.Excludes, rel) {
			return nil
		}
		included := len(cfg.Includes) == 0
		for _, p := range cfg.Includes {
			neg := strings.HasPrefix(p, "!")
			pat := strings.TrimPrefix(p, "!")
			if matchPatterns([]string{pat}, rel) {
				included = !neg
			}
		}
		if !included {
			return nil
		}
		outPath := ""
		copyOnly := matchPatterns(cfg.ExcludeProcessing, rel)
		if cfg.OutputMap != "" {
			m, rerr := r.renderOutputMap(rel)
			if rerr != nil {
				return rerr
			}
			outPath = m
		} else {
			outPath = filepath.Join(cfg.OutputDir, rel)
		}
		if copyOnly {
			b, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			out = append(out, tmplInput{name: path, text: string(b), out: outPath, mode: fi.Mode()})
			return nil
		}
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		out = append(out, tmplInput{name: path, text: string(b), out: outPath, mode: fi.Mode()})
		return nil
	})
	return out, err
}

// renderOutputMap renders the --output-map template for one input file.
func (r *renderer) renderOutputMap(rel string) (string, error) {
	omCtx := map[string]interface{}{
		"in":  filepath.ToSlash(rel),
		"ctx": r.tctx,
	}
	if m, ok := r.tctx.(map[string]interface{}); ok {
		for k, v := range m {
			if k != "in" && k != "ctx" {
				omCtx[k] = v
			}
		}
	}
	t := r.newTemplate("<outputMap>")
	tmpl, err := t.Parse(r.cfg.OutputMap)
	if err != nil {
		return "", fmt.Errorf("parse template <outputMap>: %w", err)
	}
	buf := &bytes.Buffer{}
	if err := tmpl.Execute(buf, omCtx); err != nil {
		return "", fmt.Errorf("failed to render template <outputMap>: %w", err)
	}
	return strings.TrimSpace(buf.String()), nil
}

// renderOne renders a single gathered template.
func (r *renderer) renderOne(t tmplInput) ([]byte, error) {
	return r.renderTemplate(t.name, t.text, r.tctx)
}

// writeOutput writes rendered bytes to the output target.
func (r *renderer) writeOutput(t tmplInput, out []byte) error {
	// empty/whitespace-only output is not written
	if strings.TrimSpace(string(out)) == "" {
		return nil
	}
	if t.out == "-" || t.out == "" {
		_, err := r.stdout.Write(out)
		return err
	}
	mode := t.mode
	if r.cfg.Chmod != "" {
		m, err := strconv.ParseUint(r.cfg.Chmod, 8, 32)
		if err != nil {
			return fmt.Errorf("invalid --chmod value %q: %v", r.cfg.Chmod, err)
		}
		mode = os.FileMode(m)
	}
	if dir := filepath.Dir(t.out); dir != "" && dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return err
		}
	}
	if err := os.WriteFile(t.out, out, mode); err != nil {
		return err
	}
	// ensure mode even if file existed
	if r.cfg.Chmod != "" {
		if err := os.Chmod(t.out, mode); err != nil {
			return err
		}
	}
	return nil
}

// runPostExec runs the post-template command.
func (r *renderer) runPostExec(out *bytes.Buffer) error {
	cmd := exec.CommandContext(r.deps.Ctx, r.cfg.PostExec[0], r.cfg.PostExec[1:]...)
	cmd.Stdout = r.stdout
	cmd.Stderr = r.stderr
	if r.cfg.ExecPipe {
		cmd.Stdin = out
	}
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to run post-exec command: %w", err)
	}
	return nil
}

// pluginFunc creates a template function that runs an external command.
func (r *renderer) pluginFunc(pc pluginConf) interface{} {
	return func(args ...interface{}) (string, error) {
		timeout := pc.Timeout
		if timeout == 0 {
			timeout = r.cfg.PluginTimeout
		}
		ctx, cancel := context.WithTimeout(r.deps.Ctx, timeout)
		defer cancel()

		argv := append([]string{}, pc.Args...)
		var stdinData string
		strs := make([]string, 0, len(args))
		for _, a := range args {
			strs = append(strs, fmt.Sprintf("%v", a))
		}
		if pc.Pipe && len(strs) > 0 {
			stdinData = strs[len(strs)-1]
			strs = strs[:len(strs)-1]
		}
		argv = append(argv, strs...)

		cmd := exec.CommandContext(ctx, pc.Cmd, argv...)
		if pc.Pipe {
			cmd.Stdin = strings.NewReader(stdinData)
		}
		cmd.Stderr = r.stderr
		var outBuf bytes.Buffer
		cmd.Stdout = &outBuf
		if err := cmd.Run(); err != nil {
			return "", fmt.Errorf("plugin %s failed: %w", pc.Cmd, err)
		}
		return strings.TrimRight(outBuf.String(), "\n"), nil
	}
}

// --- gitignore-ish pattern matching (simplified) ---

func loadGomplateIgnores(root string) ([]string, error) {
	var patterns []string
	b, err := os.ReadFile(filepath.Join(root, ".gomplateignore"))
	if err != nil {
		return nil, nil
	}
	for _, line := range strings.Split(string(b), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		patterns = append(patterns, line)
	}
	return patterns, nil
}

// matchPatterns reports whether rel matches any pattern (with ! negation).
func matchPatterns(patterns []string, rel string) bool {
	rel = filepath.ToSlash(rel)
	matched := false
	for _, p := range patterns {
		neg := strings.HasPrefix(p, "!")
		pat := strings.TrimPrefix(p, "!")
		if matchGitignore(pat, rel) {
			matched = !neg
		}
	}
	return matched
}

func matchGitignore(pattern, rel string) bool {
	pattern = strings.TrimPrefix(pattern, "/")
	if strings.HasSuffix(pattern, "/") {
		pattern = strings.TrimSuffix(pattern, "/")
		// directory prefix match
		if strings.HasPrefix(rel, pattern+"/") || rel == pattern {
			return true
		}
	}
	if !strings.Contains(pattern, "/") {
		// match against any path element
		for _, part := range strings.Split(rel, "/") {
			if ok, _ := pathMatch(pattern, part); ok {
				return true
			}
		}
		return false
	}
	ok, _ := pathMatch(pattern, rel)
	return ok
}

// pathMatch is like path.Match but supports **.
func pathMatch(pattern, name string) (bool, error) {
	px := strings.Split(pattern, "/")
	nx := strings.Split(name, "/")
	return matchSegments(px, nx), nil
}

func matchSegments(px, nx []string) bool {
	for len(px) > 0 {
		if px[0] == "**" {
			// ** matches zero or more segments
			if len(px) == 1 {
				return true
			}
			for i := 0; i <= len(nx); i++ {
				if matchSegments(px[1:], nx[i:]) {
					return true
				}
			}
			return false
		}
		if len(nx) == 0 {
			return false
		}
		ok, err := filepath.Match(px[0], nx[0])
		if err != nil || !ok {
			return false
		}
		px, nx = px[1:], nx[1:]
	}
	return len(nx) == 0
}

package funcs

import "os"

// Env is the env namespace object. Methods become template functions
// like env.Getenv.
type Env struct{}

func init() {
	RegisterNS("env", func(deps *Deps) interface{} { return Env{} })
}

// Getenv returns the value of the environment variable, or the default.
func (Env) Getenv(args ...interface{}) string {
	if len(args) == 0 {
		return ""
	}
	name := args[0].(string)
	if len(args) > 1 {
		if v, ok := os.LookupEnv(name); ok {
			return v
		}
		if s, ok := args[1].(string); ok {
			return s
		}
		return ""
	}
	return os.Getenv(name)
}

